import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = token;
  next();
}

// Document search endpoint with full-text search
app.get('/api/documents/search', extractTenant, async (req, res) => {
  const { q, category, limit = 20 } = req.query;

  if (!q || q.length > 200) {
    return res.status(400).json({ error: 'Invalid query' });
  }

  // Sanitize limit
  const safeLimit = Math.min(Math.max(parseInt(limit) || 20, 1), 100);

  try {
    // Build search query with tenant isolation
    let query = `
      SELECT id, title, category, ts_rank(search_vector, plainto_tsquery($1)) as rank
      FROM documents
      WHERE tenant_id = $2
        AND search_vector @@ plainto_tsquery($1)
    `;
    const params = [q, req.tenantId];

    // Category filter - VULNERABLE: direct interpolation
    if (category) {
      query += ` AND category = '${category}'`;
    }

    query += ` ORDER BY rank DESC LIMIT $${params.length + 1}`;
    params.push(safeLimit);

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document detail endpoint
app.get('/api/documents/:id', extractTenant, async (req, res) => {
  const { id } = req.params;

  // UUID validation
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) {
    return res.status(400).json({ error: 'Invalid document ID' });
  }

  try {
    const result = await pool.query(
      'SELECT id, title, body, category, created_at FROM documents WHERE id = $1 AND tenant_id = $2',
      [id, req.tenantId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});

// Bulk export endpoint
app.post('/api/documents/export', extractTenant, async (req, res) => {
  const { format = 'json', categories } = req.body;

  let query = 'SELECT id, title, category, created_at FROM documents WHERE tenant_id = $1';
  const params = [req.tenantId];

  if (categories && Array.isArray(categories)) {
    const placeholders = categories.map((_, i) => `$${i + 2}`).join(',');
    query += ` AND category IN (${placeholders})`;
    params.push(...categories);
  }

  query += ' ORDER BY created_at DESC LIMIT 1000';

  try {
    const result = await pool.query(query, params);
    if (format === 'csv') {
      const csv = result.rows.map(r => `${r.id},${r.title},${r.category}`).join('\n');
      res.set('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ documents: result.rows });
    }
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
